// `items` contains all outputs from the previous node
const result = {};

// Loop through each incoming item
for (const item of items) {
  const output = item.json.output;

  if (output && output.Interval) {
    result[output.Interval] = output;
  }
}

// Return a single merged object as output
return [
  {
    "result": result
  }
];

