// Define gold-related and macroeconomic keywords
const goldKeywords = ["gold", "xau", "precious metal", "commodities", "safe haven"];
const macroKeywords = ["usd", "inflation", "interest rate", "fed", "cpi", "fomc", "jobs", "yield", "recession", "risk sentiment"];

// Helper to convert Unix timestamp to ISO
const unixToISO = unix => new Date(unix * 1000).toISOString();

// Prepare the combined array
const relevantNews = [];

for (const item of items) {
  const news = item.json;
  const text = `${news.headline || ""} ${news.summary || ""}`.toLowerCase();

  const isGoldRelated = goldKeywords.some(k => text.includes(k));
  const isMacroRelated = macroKeywords.some(k => text.includes(k));

  if (isGoldRelated || isMacroRelated) {
    relevantNews.push({
      headline: news.headline,
      summary: news.summary,
      source: news.source,
      timestamp: unixToISO(news.datetime),
      url: news.url,
      impact: isGoldRelated
        ? "Gold-specific"
        : "Macro influence"
    });
  }
}

// Return a single item with all news under one key
return [
  {
    json: {
      label: "XAU/USD relevant news",
      articles: relevantNews
    }
  }
];

const result = {
  analysis: {},
  indicators: {},
  strategy: {},
  news: {},
};

// Helper to detect interval tags
function normalizeInterval(input) {
  const lower = input.toLowerCase();
  if (lower.includes("1day") || lower === "1d" || lower === "daily") return "daily";
  if (lower.includes("4h") || lower === "4hour") return "4hour";
  if (lower.includes("1h") || lower === "1hour") return "1hour";
  if (lower.includes("15m") || lower === "m15" || lower.includes("15min")) return "m15";
  return lower;
}

// Process incoming items
for (const item of items) {
  const json = item.json;

  // Strategy recommendation
  if (json.output?.strategy_recommendation) {
    result.strategy = json.output.strategy_recommendation;
  }

  // Daily/4H/1H Analysis Agent
  if (json.output?.Interval) {
    const key = normalizeInterval(json.output.Interval);
    result.analysis[key] = json.output;
  }

  // Indicators like DEMA
  if (json.meta?.interval && json.values) {
    const key = normalizeInterval(json.meta.interval);
    result.indicators[key] = {
      meta: json.meta,
      values: json.values,
    };
  }

  // News Articles
  if (json.articles && Array.isArray(json.articles)) {
    result.news = json;
  }

  // Add any future categories here if needed (e.g., quote, analyst_rating, etc.)
}

// Return one item
return [
  {
    "result": result
  }
];

// items[0].json contains the structured trade signal
const trade = $input.first().json.output;
const now = new Date().toISOString().split("T")[0];

// Build a row to insert into Google Sheets
return [
  {
    json: {
      symbol: trade.symbol,
      date_time: now,
      action: trade.action,
      entry: trade.entry_price,
      stop_loss: trade.stop_loss,
      take_profit: trade.take_profit,
      position_size: trade.position_size,
      confidence: trade.confidence,
      timeframe: trade.timeframe,
      trade_status: "", // default to empty, update manually or with logic
      trade_end: "",       // default empty, will be set to "tp" or "sl" later
      acct_balance: $input.first().json.acct_balance,
      ammt_risked: "",
      Leverage: "1:15",
      profit_loss: "",
      rr: ""
    }
  }
];

function getPreviousTradingDay(date) {
  const day = date.getDay(); // 0 = Sunday, 1 = Monday, ..., 6 = Saturday
  const newDate = new Date(date);

  if (day === 0) {
    // Sunday → go back to Friday
    newDate.setDate(date.getDate() - 2);
  } else if (day === 1) {
    // Monday → go back to Friday
    newDate.setDate(date.getDate() - 3);
  } else {
    // Any other weekday → go back one day
    newDate.setDate(date.getDate() - 1);
  }

  return newDate.toISOString().split("T")[0];
}

function getTodayTradingDay(date) {
  const day = date.getDay();
  if (day === 0 || day === 6) {
    return null; // Not a trading day
  }
  return date.toISOString().split("T")[0];
}

// Get dates
const today = new Date();
const todayTradingDay = getTodayTradingDay(today);
const previousTradingDay = getPreviousTradingDay(today);

// Output
return [
  {
    json: {
      today_trading_day: todayTradingDay,
      previous_trading_day: previousTradingDay
    }
  }
];
